-- create-table /RT/DOMAINS
CREATE TABLE "/RT/DOMAINS" (
  "DOMAIN_NAME" TEXT NOT NULL,
  "PACKAGE_ID" TEXT,
  "DESCRIPTION" TEXT,
  "BASE_TYPE" TEXT NOT NULL,
  "LENGTH" INTEGER,
  "DECIMALS" INTEGER,
  CONSTRAINT "/RT/DOMAINS#PK" PRIMARY KEY ("DOMAIN_NAME"),
  CONSTRAINT "/RT/DOMAINS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID"),
  CONSTRAINT "/RT/DOMAINS#CK#DOMAIN_NAME" CHECK ("DOMAIN_NAME" IS NULL OR (length("DOMAIN_NAME") <= 63)),
  CONSTRAINT "/RT/DOMAINS#CK#PACKAGE_ID" CHECK ("PACKAGE_ID" IS NULL OR (length("PACKAGE_ID") <= 16)),
  CONSTRAINT "/RT/DOMAINS#CK#BASE_TYPE" CHECK ("BASE_TYPE" IS NULL OR (length("BASE_TYPE") <= 10 AND "BASE_TYPE" IN ('CHAR', 'STRING', 'INT4', 'INT8', 'DEC', 'DATE', 'TIMESTAMP', 'BOOL', 'UUID', 'BLOB'))),
  CONSTRAINT "/RT/DOMAINS#CK#LENGTH" CHECK ("LENGTH" IS NULL OR ("LENGTH" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/RT/DOMAINS#CK#DECIMALS" CHECK ("DECIMALS" IS NULL OR ("DECIMALS" BETWEEN -2147483648 AND 2147483647))
) STRICT;

-- create-table /RT/DOMAIN_VALUES
CREATE TABLE "/RT/DOMAIN_VALUES" (
  "DOMAIN_NAME" TEXT NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "VALUE" TEXT NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/DOMAIN_VALUES#PK" PRIMARY KEY ("DOMAIN_NAME", "POSITION"),
  CONSTRAINT "/RT/DOMAIN_VALUES#FK#DOMAIN" FOREIGN KEY ("DOMAIN_NAME") REFERENCES "/RT/DOMAINS" ("DOMAIN_NAME"),
  CONSTRAINT "/RT/DOMAIN_VALUES#CK#DOMAIN_NAME" CHECK ("DOMAIN_NAME" IS NULL OR (length("DOMAIN_NAME") <= 63)),
  CONSTRAINT "/RT/DOMAIN_VALUES#CK#POSITION" CHECK ("POSITION" IS NULL OR ("POSITION" BETWEEN -2147483648 AND 2147483647))
) STRICT;

-- create-table /RT/EXTENSIONS
CREATE TABLE "/RT/EXTENSIONS" (
  "PACKAGE_ID" TEXT NOT NULL,
  "TABLE_NAME" TEXT NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/EXTENSIONS#PK" PRIMARY KEY ("PACKAGE_ID", "TABLE_NAME"),
  CONSTRAINT "/RT/EXTENSIONS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID"),
  CONSTRAINT "/RT/EXTENSIONS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME"),
  CONSTRAINT "/RT/EXTENSIONS#CK#PACKAGE_ID" CHECK ("PACKAGE_ID" IS NULL OR (length("PACKAGE_ID") <= 16)),
  CONSTRAINT "/RT/EXTENSIONS#CK#TABLE_NAME" CHECK ("TABLE_NAME" IS NULL OR (length("TABLE_NAME") <= 63))
) STRICT;

-- create-table /RT/FIELDS
CREATE TABLE "/RT/FIELDS" (
  "TABLE_NAME" TEXT NOT NULL,
  "FIELD_NAME" TEXT NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "LOCAL_NAME" TEXT NOT NULL,
  "DESCRIPTION" TEXT,
  "PACKAGE_ID" TEXT,
  "ORIGIN" TEXT NOT NULL,
  "DOMAIN_NAME" TEXT NOT NULL,
  "NOT_NULL" INTEGER NOT NULL,
  "DEFAULT_VALUE" TEXT,
  "KEY_POSITION" INTEGER,
  CONSTRAINT "/RT/FIELDS#PK" PRIMARY KEY ("TABLE_NAME", "FIELD_NAME"),
  CONSTRAINT "/RT/FIELDS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME"),
  CONSTRAINT "/RT/FIELDS#FK#DOMAIN" FOREIGN KEY ("DOMAIN_NAME") REFERENCES "/RT/DOMAINS" ("DOMAIN_NAME"),
  CONSTRAINT "/RT/FIELDS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID"),
  CONSTRAINT "/RT/FIELDS#CK#TABLE_NAME" CHECK ("TABLE_NAME" IS NULL OR (length("TABLE_NAME") <= 63)),
  CONSTRAINT "/RT/FIELDS#CK#FIELD_NAME" CHECK ("FIELD_NAME" IS NULL OR (length("FIELD_NAME") <= 63)),
  CONSTRAINT "/RT/FIELDS#CK#POSITION" CHECK ("POSITION" IS NULL OR ("POSITION" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/RT/FIELDS#CK#LOCAL_NAME" CHECK ("LOCAL_NAME" IS NULL OR (length("LOCAL_NAME") <= 63)),
  CONSTRAINT "/RT/FIELDS#CK#PACKAGE_ID" CHECK ("PACKAGE_ID" IS NULL OR (length("PACKAGE_ID") <= 16)),
  CONSTRAINT "/RT/FIELDS#CK#ORIGIN" CHECK ("ORIGIN" IS NULL OR (length("ORIGIN") <= 10 AND "ORIGIN" IN ('TABLE', 'EXTENSION', 'TENANT'))),
  CONSTRAINT "/RT/FIELDS#CK#DOMAIN_NAME" CHECK ("DOMAIN_NAME" IS NULL OR (length("DOMAIN_NAME") <= 63)),
  CONSTRAINT "/RT/FIELDS#CK#NOT_NULL" CHECK ("NOT_NULL" IS NULL OR ("NOT_NULL" IN (0, 1))),
  CONSTRAINT "/RT/FIELDS#CK#KEY_POSITION" CHECK ("KEY_POSITION" IS NULL OR ("KEY_POSITION" BETWEEN -2147483648 AND 2147483647))
) STRICT;

-- create-table /RT/FK_FIELDS
CREATE TABLE "/RT/FK_FIELDS" (
  "TABLE_NAME" TEXT NOT NULL,
  "FK_NAME" TEXT NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FIELD_NAME" TEXT NOT NULL,
  "TARGET_FIELD" TEXT NOT NULL,
  CONSTRAINT "/RT/FK_FIELDS#PK" PRIMARY KEY ("TABLE_NAME", "FK_NAME", "POSITION"),
  CONSTRAINT "/RT/FK_FIELDS#FK#FOREIGN_KEY" FOREIGN KEY ("TABLE_NAME", "FK_NAME") REFERENCES "/RT/FOREIGN_KEYS" ("TABLE_NAME", "FK_NAME"),
  CONSTRAINT "/RT/FK_FIELDS#CK#TABLE_NAME" CHECK ("TABLE_NAME" IS NULL OR (length("TABLE_NAME") <= 63)),
  CONSTRAINT "/RT/FK_FIELDS#CK#FK_NAME" CHECK ("FK_NAME" IS NULL OR (length("FK_NAME") <= 63)),
  CONSTRAINT "/RT/FK_FIELDS#CK#POSITION" CHECK ("POSITION" IS NULL OR ("POSITION" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/RT/FK_FIELDS#CK#FIELD_NAME" CHECK ("FIELD_NAME" IS NULL OR (length("FIELD_NAME") <= 63)),
  CONSTRAINT "/RT/FK_FIELDS#CK#TARGET_FIELD" CHECK ("TARGET_FIELD" IS NULL OR (length("TARGET_FIELD") <= 63))
) STRICT;

-- create-table /RT/FOREIGN_KEYS
CREATE TABLE "/RT/FOREIGN_KEYS" (
  "TABLE_NAME" TEXT NOT NULL,
  "FK_NAME" TEXT NOT NULL,
  "PACKAGE_ID" TEXT,
  "ORIGIN" TEXT NOT NULL,
  "TARGET_TABLE" TEXT NOT NULL,
  CONSTRAINT "/RT/FOREIGN_KEYS#PK" PRIMARY KEY ("TABLE_NAME", "FK_NAME"),
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME"),
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#TARGET" FOREIGN KEY ("TARGET_TABLE") REFERENCES "/RT/TABLES" ("TABLE_NAME"),
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID"),
  CONSTRAINT "/RT/FOREIGN_KEYS#CK#TABLE_NAME" CHECK ("TABLE_NAME" IS NULL OR (length("TABLE_NAME") <= 63)),
  CONSTRAINT "/RT/FOREIGN_KEYS#CK#FK_NAME" CHECK ("FK_NAME" IS NULL OR (length("FK_NAME") <= 63)),
  CONSTRAINT "/RT/FOREIGN_KEYS#CK#PACKAGE_ID" CHECK ("PACKAGE_ID" IS NULL OR (length("PACKAGE_ID") <= 16)),
  CONSTRAINT "/RT/FOREIGN_KEYS#CK#ORIGIN" CHECK ("ORIGIN" IS NULL OR (length("ORIGIN") <= 10 AND "ORIGIN" IN ('TABLE', 'EXTENSION', 'TENANT'))),
  CONSTRAINT "/RT/FOREIGN_KEYS#CK#TARGET_TABLE" CHECK ("TARGET_TABLE" IS NULL OR (length("TARGET_TABLE") <= 63))
) STRICT;

-- create-table /RT/LOG
CREATE TABLE "/RT/LOG" (
  "LOG_ID" TEXT NOT NULL,
  "OPERATION" TEXT NOT NULL,
  "TARGET" TEXT,
  "STARTED_AT" TEXT NOT NULL,
  "FINISHED_AT" TEXT NOT NULL,
  "STATUS" TEXT NOT NULL,
  "MESSAGE" TEXT,
  CONSTRAINT "/RT/LOG#PK" PRIMARY KEY ("LOG_ID"),
  CONSTRAINT "/RT/LOG#CK#LOG_ID" CHECK ("LOG_ID" IS NULL OR ("LOG_ID" GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]')),
  CONSTRAINT "/RT/LOG#CK#OPERATION" CHECK ("OPERATION" IS NULL OR (length("OPERATION") <= 16 AND "OPERATION" IN ('MIGRATE', 'INSTALL', 'UPGRADE', 'UNINSTALL', 'TENANT_DELETE'))),
  CONSTRAINT "/RT/LOG#CK#TARGET" CHECK ("TARGET" IS NULL OR (length("TARGET") <= 63)),
  CONSTRAINT "/RT/LOG#CK#STARTED_AT" CHECK ("STARTED_AT" IS NULL OR ("STARTED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("STARTED_AT", 1, 19)) IS substr("STARTED_AT", 1, 19))),
  CONSTRAINT "/RT/LOG#CK#FINISHED_AT" CHECK ("FINISHED_AT" IS NULL OR ("FINISHED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("FINISHED_AT", 1, 19)) IS substr("FINISHED_AT", 1, 19))),
  CONSTRAINT "/RT/LOG#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('SUCCESS', 'FAILED')))
) STRICT;

-- create-table /RT/LOG_PACKAGES
CREATE TABLE "/RT/LOG_PACKAGES" (
  "LOG_ID" TEXT NOT NULL,
  "PACKAGE_ID" TEXT NOT NULL,
  "VERSION_FROM" TEXT,
  "VERSION_TO" TEXT,
  CONSTRAINT "/RT/LOG_PACKAGES#PK" PRIMARY KEY ("LOG_ID", "PACKAGE_ID"),
  CONSTRAINT "/RT/LOG_PACKAGES#FK#LOG" FOREIGN KEY ("LOG_ID") REFERENCES "/RT/LOG" ("LOG_ID"),
  CONSTRAINT "/RT/LOG_PACKAGES#CK#LOG_ID" CHECK ("LOG_ID" IS NULL OR ("LOG_ID" GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]')),
  CONSTRAINT "/RT/LOG_PACKAGES#CK#PACKAGE_ID" CHECK ("PACKAGE_ID" IS NULL OR (length("PACKAGE_ID") <= 16)),
  CONSTRAINT "/RT/LOG_PACKAGES#CK#VERSION_FROM" CHECK ("VERSION_FROM" IS NULL OR (length("VERSION_FROM") <= 64)),
  CONSTRAINT "/RT/LOG_PACKAGES#CK#VERSION_TO" CHECK ("VERSION_TO" IS NULL OR (length("VERSION_TO") <= 64))
) STRICT;

-- create-table /RT/LOG_STATEMENTS
CREATE TABLE "/RT/LOG_STATEMENTS" (
  "LOG_ID" TEXT NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "STATEMENT" TEXT NOT NULL,
  "DESTRUCTIVE" INTEGER NOT NULL,
  CONSTRAINT "/RT/LOG_STATEMENTS#PK" PRIMARY KEY ("LOG_ID", "POSITION"),
  CONSTRAINT "/RT/LOG_STATEMENTS#FK#LOG" FOREIGN KEY ("LOG_ID") REFERENCES "/RT/LOG" ("LOG_ID"),
  CONSTRAINT "/RT/LOG_STATEMENTS#CK#LOG_ID" CHECK ("LOG_ID" IS NULL OR ("LOG_ID" GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]')),
  CONSTRAINT "/RT/LOG_STATEMENTS#CK#POSITION" CHECK ("POSITION" IS NULL OR ("POSITION" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/RT/LOG_STATEMENTS#CK#DESTRUCTIVE" CHECK ("DESTRUCTIVE" IS NULL OR ("DESTRUCTIVE" IN (0, 1)))
) STRICT;

-- create-table /RT/MIGRATIONS
CREATE TABLE "/RT/MIGRATIONS" (
  "VERSION" INTEGER NOT NULL,
  "APPLIED_AT" TEXT NOT NULL,
  CONSTRAINT "/RT/MIGRATIONS#PK" PRIMARY KEY ("VERSION"),
  CONSTRAINT "/RT/MIGRATIONS#CK#VERSION" CHECK ("VERSION" IS NULL OR ("VERSION" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/RT/MIGRATIONS#CK#APPLIED_AT" CHECK ("APPLIED_AT" IS NULL OR ("APPLIED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("APPLIED_AT", 1, 19)) IS substr("APPLIED_AT", 1, 19)))
) STRICT;

-- create-table /RT/PACKAGES
CREATE TABLE "/RT/PACKAGES" (
  "PACKAGE_ID" TEXT NOT NULL,
