  CONSTRAINT "/RT/PACKAGES#CK#UPDATED_AT" CHECK ("UPDATED_AT" IS NULL OR ("UPDATED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("UPDATED_AT", 1, 19)) IS substr("UPDATED_AT", 1, 19)))
) STRICT;

